-- Selling approvals (docs/engineering/listing-rules.md sections 1, 2 and 5): Amazon-style "sell, apply or not available" per
-- scope, approvals per organisation with documents and expiry, a staff case per application (same two-step review, assignment,
-- SLA and escalation as seller applications) and staff-editable rules. The category rules are seeded from
-- tools/listing-rules/rules.json (python3 tools/listing-rules/gen_selling_seed.py --check <this file> verifies it).

create table selling_rule (
    id                  uuid primary key,
    scope_type          varchar(24)  not null check (scope_type in ('CATEGORY', 'PRODUCT_TYPE', 'BRAND', 'BRAND_IN_CATEGORY',
                                                                     'PRODUCT', 'CAPABILITY')),
    scope_key           varchar(200) not null,
    scope_label         varchar(200) not null,
    level               varchar(16)  not null check (level in ('SELL', 'APPLY', 'NOT_AVAILABLE')),
    required_documents  jsonb        not null default '[]',
    reason              varchar(500) not null default '',
    note                varchar(500) not null default '',
    approval_level      varchar(32),
    capability          varchar(40),
    condition_materials jsonb        not null default '[]',
    condition_watch     boolean      not null default false,
    reapply_after_days  int          not null default 30 check (reapply_after_days between 1 and 730),
    active              boolean      not null default true,
    source              varchar(8)   not null default 'STAFF' check (source in ('SEED', 'STAFF')),
    updated_at          timestamptz  not null default now(),
    updated_by          varchar(80),
    updated_by_name     varchar(200),
    version             bigint       not null default 0,
    unique (scope_type, scope_key)
);
create index selling_rule_level on selling_rule (level) where active;

create table selling_rule_audit (
    id          uuid primary key,
    rule_id     uuid         not null references selling_rule (id),
    action      varchar(16)  not null,
    actor_id    varchar(80)  not null,
    actor_name  varchar(200),
    reason      varchar(500) not null,
    before_json jsonb,
    after_json  jsonb        not null,
    changed_at  timestamptz  not null
);
create index selling_rule_audit_rule on selling_rule_audit (rule_id, changed_at desc);

create sequence selling_application_reference_seq start with 50000;

create table selling_application (
    id                 varchar(40)  primary key,
    reference          varchar(20)  not null unique,
    org_id             varchar(40)  not null references organisation (id),
    applicant_user_id  varchar(80)  not null,
    applicant_name     varchar(200),
    scope_type         varchar(24)  not null,
    scope_key          varchar(200) not null,
    scope_label        varchar(200) not null,
    rule_id            uuid         references selling_rule (id),
    kind               varchar(8)   not null check (kind in ('NEW', 'RENEWAL')),
    source             varchar(12)  not null default 'SELLER' check (source in ('SELLER', 'MIGRATION')),
    status             varchar(32)  not null check (status in ('PENDING_REVIEW', 'FLAGGED', 'AWAITING_FINAL_APPROVAL',
                                                               'INFO_REQUESTED', 'APPROVED', 'REJECTED')),
    documents          jsonb        not null default '[]',
    note               text,
    reviewer_id        varchar(80),
    reviewed_at        timestamptz,
    final_approver_id  varchar(80),
    decided_at         timestamptz,
    failed_checks      jsonb        not null default '[]',
    requested_items    jsonb        not null default '[]',
    reason_code        varchar(60),
    decision_note      text,
    disqualified       boolean      not null default false,
    reapply_after      date,
    submission_count   int          not null default 1,
    submitted_at       timestamptz,
    created_at         timestamptz  not null,
    updated_at         timestamptz  not null,
    version            bigint       not null default 0,
    constraint selling_application_two_people check (final_approver_id is null or reviewer_id is null
                                                     or final_approver_id <> reviewer_id),
    constraint selling_application_disqualified_date check (not disqualified or reapply_after is not null)
);
create index selling_application_queue on selling_application (status, submitted_at);
create index selling_application_org on selling_application (org_id, created_at desc);
-- One application in progress per organisation and scope (a double submit and a re-run of the migration add none).
create unique index selling_application_open on selling_application (org_id, scope_type, scope_key)
    where status in ('PENDING_REVIEW', 'FLAGGED', 'AWAITING_FINAL_APPROVAL', 'INFO_REQUESTED');

create table selling_application_event (
    id             uuid         primary key,
    application_id varchar(40)  not null references selling_application (id),
    action         varchar(32)  not null,
    from_status    varchar(32),
    to_status      varchar(32)  not null,
    actor_id       varchar(80)  not null,
    actor_name     varchar(200),
    reason_code    varchar(60),
    note           text,
    items          jsonb        not null default '[]',
    request_key    varchar(128),
    occurred_at    timestamptz  not null
);
create index selling_application_event_app on selling_application_event (application_id, occurred_at);
create unique index selling_application_event_key on selling_application_event (application_id, request_key)
    where request_key is not null;

create table selling_document_access (
    id             uuid         primary key,
    application_id varchar(40)  not null references selling_application (id),
    asset_id       varchar(80)  not null,
    kind           varchar(32)  not null,
    viewer_id      varchar(80)  not null,
    viewed_at      timestamptz  not null
);
create index selling_document_access_app on selling_document_access (application_id, viewed_at);

-- Who holds each selling application: the same columns and meaning as application_case.
create table selling_case (
    application_id           varchar(40) primary key references selling_application (id),
    stage                    varchar(10) check (stage in ('REVIEW', 'APPROVAL')),
    assignee_id              varchar(80),
    assignee_name            varchar(200),
    assigned_by_id           varchar(80),
    assigned_by_name         varchar(200),
    assigned_at              timestamptz,
    stage_entered_at         timestamptz not null,
    escalation_level         int         not null default 0 check (escalation_level between 0 and 2),
    escalated_at             timestamptz,
    escalation_reason        varchar(500),
    escalation_target_ids    jsonb       not null default '[]',
    escalation_target_names  jsonb       not null default '[]',
    returned_by_id           varchar(80),
    returned_by_name         varchar(200),
    returned_at              timestamptz,
    return_note              text,
    return_count             int         not null default 0,
    updated_at               timestamptz not null,
    version                  bigint      not null default 0
);
create index selling_case_assignee on selling_case (assignee_id) where assignee_id is not null;
create index selling_case_stage on selling_case (stage, stage_entered_at);

create table selling_approval (
    id                  uuid primary key,
    org_id              varchar(40)  not null references organisation (id),
    scope_type          varchar(24)  not null,
    scope_key           varchar(200) not null,
    scope_label         varchar(200) not null,
    rule_id             uuid         references selling_rule (id),
    status              varchar(16)  not null check (status in ('APPLIED', 'NEEDS_ATTENTION', 'APPROVED', 'EXPIRED',
                                                                'NOT_AVAILABLE')),
    reason              varchar(500),
    reapply_after       date,
    approved_at         timestamptz,
    expires_at          timestamptz,
    documents           jsonb        not null default '[]',
    application_id      varchar(40),
    paused              boolean      not null default false,
    pause_reason        varchar(500),
    paused_at           timestamptz,
    listings_paused     boolean      not null default false,
    warned_30_at        timestamptz,
    warned_14_at        timestamptz,
    warned_7_at         timestamptz,
    expired_notified_at timestamptz,
    created_at          timestamptz  not null,
    updated_at          timestamptz  not null,
    version             bigint       not null default 0,
    unique (org_id, scope_type, scope_key)
);
create index selling_approval_expiry on selling_approval (expires_at) where status in ('APPROVED', 'EXPIRED');

on conflict (code) do nothing;

-- Seeded rules
